CREATE FUNCTION public.create_marketplace_offer(conversation_value uuid,terms_value text,milestones_value jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c record; cid uuid; total numeric; item jsonb; pos integer:=0; curr text; BEGIN IF NOT public.conversation_participant(conversation_value) OR NOT public.is_buyer() THEN RAISE EXCEPTION 'Conversation unavailable'; END IF; SELECT * INTO c FROM public.marketplace_conversations WHERE id=conversation_value AND buyer_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Only the buyer can send offers'; END IF; IF EXISTS(SELECT 1 FROM public.marketplace_contracts WHERE conversation_id=conversation_value) THEN SELECT id INTO cid FROM public.marketplace_contracts WHERE conversation_id=conversation_value; RETURN cid; END IF; IF char_length(trim(terms_value)) NOT BETWEEN 20 AND 8000 OR jsonb_typeof(milestones_value)<>'array' OR jsonb_array_length(milestones_value) NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Add terms and 1 to 20 milestones'; END IF; SELECT sum((x->>'amount')::numeric) INTO total FROM jsonb_array_elements(milestones_value)x; SELECT j.budget_currency INTO curr FROM public.jobs j JOIN public.job_applications a ON a.job_id=j.id WHERE a.id=c.application_id AND a.status NOT IN('withdrawn','rejected'); IF curr IS NULL THEN RAISE EXCEPTION 'Application no longer eligible'; END IF; INSERT INTO public.marketplace_contracts(conversation_id,buyer_id,seller_id,title,terms,amount,currency) VALUES(c.id,c.buyer_id,c.seller_id,c.title,trim(terms_value),total,curr) RETURNING id INTO cid; FOR item IN SELECT * FROM jsonb_array_elements(milestones_value) LOOP INSERT INTO public.marketplace_milestones(contract_id,title,amount,due_date,position) VALUES(cid,trim(item->>'title'),(item->>'amount')::numeric,nullif(item->>'due_date','')::date,pos); pos:=pos+1; END LOOP; INSERT INTO public.marketplace_notifications(user_id,conversation_id,kind) VALUES(c.seller_id,c.id,'offer'); RETURN cid; END $$;
CREATE FUNCTION public.respond_marketplace_offer(contract_value uuid,action_value text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c record; desired text; BEGIN SELECT * INTO c FROM public.marketplace_contracts WHERE id=contract_value FOR UPDATE; IF NOT FOUND OR NOT public.conversation_participant(c.conversation_id) THEN RAISE EXCEPTION 'Offer unavailable'; END IF; IF action_value IN('accept','decline') THEN IF auth.uid()<>c.seller_id OR NOT public.is_seller() THEN RAISE EXCEPTION 'Only the seller can respond'; END IF; desired:=CASE WHEN action_value='accept' THEN 'accepted_unfunded' ELSE 'declined' END; IF c.status=desired THEN RETURN; END IF; IF c.status<>'offered' THEN RAISE EXCEPTION 'Offer already resolved'; END IF; UPDATE public.marketplace_contracts SET status=desired,accepted_at=CASE WHEN action_value='accept' THEN now() ELSE NULL END WHERE id=c.id; INSERT INTO public.marketplace_notifications(user_id,conversation_id,kind) VALUES(c.buyer_id,c.conversation_id,CASE WHEN action_value='accept' THEN 'accepted' ELSE 'declined' END); ELSIF action_value='cancel' AND auth.uid()=c.buyer_id THEN IF c.status='cancelled' THEN RETURN; END IF; IF c.status NOT IN('offered','accepted_unfunded') THEN RAISE EXCEPTION 'Offer already resolved'; END IF; UPDATE public.marketplace_contracts SET status='cancelled' WHERE id=c.id; INSERT INTO public.marketplace_notifications(user_id,conversation_id,kind) VALUES(c.seller_id,c.conversation_id,'cancelled'); ELSE RAISE EXCEPTION 'Action unavailable'; END IF; END $$;
REVOKE ALL ON FUNCTION public.create_marketplace_offer(uuid,text,jsonb),public.respond_marketplace_offer(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_marketplace_offer(uuid,text,jsonb),public.respond_marketplace_offer(uuid,text) TO authenticated;